commands.command:
"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$planPath = (Resolve-Path -LiteralPath '"'MANAGER_PLAN.md').Path
"'$plan = [System.IO.File]::ReadAllText($planPath, [System.Text.Encoding]::UTF8)
$required = @('"'Phase 0: Contract Freeze Gate','C1 — Parser and Validation','C2 — Ordered Batch Persistence','C3 — Command Integration and End-to-End Coverage','Review Handoff','Verification commands','Acceptance criteria','Exclusive file ownership','Dependencies')
foreach ("'$item in $required) {
  if (-not $plan.Contains($item)) { throw "Missing required plan section: $item" }
}
$changedTracked = @(git ls-files --modified --deleted)
if ($changedTracked.Count -ne 0) { throw "Tracked files changed unexpectedly: $($changedTracked -join '"', ')\" }
"'$status = @(git status --short)
if (($status.Count -ne 1) -or ($status[0] -ne '"'?? MANAGER_PLAN.md')) { throw \"Unexpected worktree status: "'$($status -join '"', ')\" }
Get-Date -Format 'yyyy-MM-dd HH:mm:ss zzz'
Get-Item -LiteralPath 'MANAGER_PLAN.md' | Select-Object Name,Length,LastWriteTime
[PSCustomObject]@{ RequiredSections = "'$required.Count; LineCount = ($plan -split "`r?`n").Count; GitStatus = $status[0]; TrackedFilesModified = $changedTracked.Count }'
